    'The authenticated server uses this endpoint too. Requests without an access token go to the public server, so MCP clients can’t discover how to sign in at this endpoint.' => '인증된 서버도 이 엔드포인트를 사용합니다. 액세스 토큰이 없는 요청은 공개 서버로 전달되므로, MCP 클라이언트는 이 엔드포인트에서 로그인 방법을 검색할 수 없습니다.',
    'The condition isn’t valid.' => '조건이 올바르지 않습니다.',
    'The draft can’t be added to a scheduled release until it’s ready to publish: {errors}' => '게시할 준비가 될 때까지 드래프트를 예약된 릴리스에 추가할 수 없습니다: {errors}',
    'The draft could not be published.' => '드래프트를 게시할 수 없습니다.',
    'The draft could not be validated for publication.' => '게시를 위한 드래프트 유효성 검사를 할 수 없습니다.',
    'The draft is not attached to that release.' => '드래프트가 해당 릴리스에 첨부되어 있지 않습니다.',
    'The draft is not attached to this release.' => '드래프트가 이 릴리스에 첨부되어 있지 않습니다.',
    'The draft must complete its approval workflow before it can be added or published.' => '드래프트를 추가하거나 게시하려면 먼저 승인 워크플로를 완료해야 합니다.',
    'The draft no longer exists.' => '드래프트가 더 이상 존재하지 않습니다.',
    'The file “{filename}” has already been added.' => '“{filename}” 파일이 이미 추가되었습니다.',
    'The first time your assistant connects, it opens a browser window where you sign in and approve access.' => '어시스턴트가 처음 연결되면 브라우저 창이 열리고, 그곳에서 로그인하고 액세스를 승인합니다.',
    'The folder is already in the selected location.' => '폴더가 이미 선택한 위치에 있습니다.',
    'The following items were not indexed.' => '다음 항목은 인덱싱되지 않았습니다.',
    'The last publication attempt failed: {error}' => '마지막 게시 시도가 실패했습니다: {error}',
    'The live element changed after this draft was prepared.' => '이 드래프트를 준비한 후 라이브 요소가 변경되었습니다.',
    'The minimum number of approvals required in total or per reviewer group.' => '전체 또는 검토자 그룹별로 필요한 최소 승인 수입니다.',
    'The navigation everyone gets. User group navigations build on it.' => '모든 사용자가 사용하는 탐색 메뉴입니다. 사용자 그룹 탐색 메뉴는 이를 기반으로 합니다.',
    'The nested element field is no longer available.' => '중첩된 요소 필드를 더 이상 사용할 수 없습니다.',
    'The release draft no longer exists.' => '릴리스 드래프트가 더 이상 존재하지 않습니다.',
    'The release has no drafts.' => '릴리스에 드래프트가 없습니다.',
    'The release is no longer scheduled.' => '릴리스가 더 이상 예약되어 있지 않습니다.',
    'The release is not due yet.' => '릴리스 예정 시간이 아직 되지 않았습니다.',
    'The release is not ready to be scheduled.' => '릴리스를 예약할 준비가 되지 않았습니다.',
    'The release no longer exists.' => '릴리스가 더 이상 존재하지 않습니다.',
    'The release “{name}” could not be published. {error}' => '“{name}” 릴리스를 게시할 수 없습니다. {error}',
    'The reserved [craft] asset transformer must use the [craft] driver.' => '예약된 [craft] 에셋 변환기는 [craft] 드라이버를 사용해야 합니다.',
    'The review for “{entry}” was reset because its workflow changed.' => '워크플로가 변경되어 “{entry}”의 검토가 초기화되었습니다.',
    'The route is invalid.' => '경로가 잘못되었습니다.',
    'The scheduled publication time must be in the future.' => '예약된 게시 시간은 미래여야 합니다.',
    'The selected asset transform driver has invalid settings.' => '선택한 에셋 변환 드라이버의 설정이 잘못되었습니다.',
    'The selected asset transform driver is unavailable.' => '선택한 에셋 변환 드라이버를 사용할 수 없습니다.',
    'The selected condition rule is invalid.' => '선택한 조건 규칙이 잘못되었습니다.',
    'The selected table cell type is unavailable.' => '선택한 테이블 셀 유형을 사용할 수 없습니다.',
    'The target folder provided for uploading is not valid.' => '업로드용으로 제공된 대상 폴더가 올바르지 않습니다.',
    'The workflow could not be updated.' => '워크플로를 업데이트할 수 없습니다.',
    'The {type} has been deleted.' => '{type}이(가) 삭제되었습니다.',
    'There are no jobs in the queue' => '큐에 작업이 없습니다',
    'There aren\'t any pending project config changes to apply.' => '적용할 대기 중인 프로젝트 구성 변경 사항이 없습니다.',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to search and read this site’s public content in plain language.' => '이 URL은 웹 페이지가 아니라 AI 어시스턴트용 MCP 서버입니다. 어시스턴트에 추가하면 이 사이트의 공개 콘텐츠를 자연어로 검색하고 읽을 수 있습니다.',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to work with this site’s content and settings in plain language.' => '이 URL은 웹 페이지가 아니라 AI 어시스턴트용 MCP 서버입니다. 어시스턴트에 추가하면 이 사이트의 콘텐츠와 설정을 자연어로 작업할 수 있습니다.',
    'This application will be able to:' => '이 애플리케이션은 다음을 수행할 수 있습니다:',
    'This asset transformer cannot be deleted because it is assigned to a volume.' => '이 에셋 변환기는 볼륨에 할당되어 있으므로 삭제할 수 없습니다.',
    'This asset transformer cannot be deleted because it is configured as the default.' => '이 에셋 변환기는 기본값으로 구성되어 있으므로 삭제할 수 없습니다.',
    'This asset transformer cannot be deleted because it is registered in code.' => 'This asset transformer cannot be deleted because it is registered in code.',
    'This asset transformer’s driver is unavailable.' => '이 에셋 변환기의 드라이버를 사용할 수 없습니다.',
    'This asset transformer’s driver is unavailable. Select an available driver to save it.' => '이 에셋 변환기의 드라이버를 사용할 수 없습니다. 저장하려면 사용 가능한 드라이버를 선택하십시오.',
    'This column type has no settings.' => '이 열 유형에는 설정이 없습니다.',
    'This date is for planning only. Scheduling is a separate action.' => '이 날짜는 계획용일 뿐입니다. 예약은 별도의 작업입니다.',
    'This date is for planning only. The release will not publish until it is explicitly scheduled.' => '이 날짜는 계획용일 뿐입니다. 명시적으로 예약하기 전에는 릴리스가 게시되지 않습니다.',
    'This disk has been reserved for temporary asset uploads. Please choose a different one for your volume.' => '이 디스크는 임시 에셋 업로드용으로 예약되어 있습니다. 볼륨에 다른 디스크를 선택하십시오.',
    'This disk reference is invalid.' => '이 디스크 참조가 잘못되었습니다.',
    'This draft already belongs to an active release.' => '이 드래프트는 이미 활성 릴리스에 속해 있습니다.',
    'This draft belongs to the scheduled release “{name}”. Saved changes will be included when the release publishes.' => '이 드래프트는 예약된 릴리스 “{name}”에 속해 있습니다. 저장된 변경 사항은 릴리스가 게시될 때 포함됩니다.',
    'This draft belongs to “{name}”. Saved changes will be included when the release publishes.' => '이 드래프트는 “{name}”에 속해 있습니다. 저장된 변경 사항은 릴리스가 게시될 때 포함됩니다.',
    'This draft is approved and ready to be published.' => '이 드래프트는 승인되었으며 게시할 준비가 되었습니다.',
    'This draft is blocking the scheduled release “{name}”.' => '이 드래프트가 예약된 릴리스 “{name}”을(를) 차단하고 있습니다.',
    'This draft is blocking “{name}”.' => '이 드래프트가 “{name}”을(를) 차단하고 있습니다.',
    'This draft is now blocking “{name}”.' => '이제 이 드래프트가 “{name}”을(를) 차단하고 있습니다.',
    'This draft is scheduled to publish with “{name}”. If edits leave it unready, the release will fail to publish.' => '이 드래프트는 “{name}”과(와) 함께 게시될 예정입니다. 편집으로 인해 준비되지 않은 상태가 되면 릴리스 게시가 실패합니다.',
    'This draft is waiting on your approval.' => '이 드래프트가 회원님의 승인을 기다리고 있습니다.',
    'This draft links to unpublished content that is not part of the release.' => '이 드래프트는 릴리스에 포함되지 않은 게시되지 않은 콘텐츠에 링크되어 있습니다.',
    'This draft must be approved before it can be applied.' => '이 드래프트를 적용하려면 먼저 승인을 받아야 합니다.',
    'This draft was withdrawn from review.' => '이 드래프트는 검토에서 철회되었습니다.',
    'This draft was withdrawn from review. Resubmit it when your edits are ready.' => '이 드래프트는 검토에서 철회되었습니다. 편집이 끝나면 다시 제출하십시오.',
    'This draft’s release is being published.' => '이 드래프트의 릴리스가 게시되는 중입니다.',
    'This endpoint is in the control panel, so only users with control panel access can use it.' => '이 엔드포인트는 제어판 안에 있으므로 제어판 액세스 권한이 있는 사용자만 사용할 수 있습니다.',
    'This entry will be expired in at least one site at the release time.' => '릴리스 시점에 이 항목은 하나 이상의 사이트에서 만료됩니다.',
    'This entry will remain pending in at least one site at the release time.' => '릴리스 시점에 이 항목은 하나 이상의 사이트에서 대기 상태로 남습니다.',
    'This field cannot be edited here.' => '이 필드는 여기에서 편집할 수 없습니다.',
    'This field is required.' => '이 필드는 필수입니다.',
    'This is a read-only view.' => '읽기 전용 보기입니다.',
    'This link type is no longer available.' => '이 링크 유형은 더 이상 사용할 수 없습니다.',
    'This option is disabled for ephemeral environments.' => '이 옵션은 임시 환경에서 비활성화되어 있습니다.',
    'This page' => '이 페이지',
    'This release already contains a draft for that element.' => '이 릴리스에는 해당 요소의 드래프트가 이미 포함되어 있습니다.',
    'This release cannot be published in its current state.' => '현재 상태에서는 이 릴리스를 게시할 수 없습니다.',
    'This release has no drafts to preview.' => '이 릴리스에는 미리 볼 드래프트가 없습니다.',
    'This review is no longer current. Refresh and try again.' => '이 검토는 더 이상 최신 상태가 아닙니다. 새로 고친 후 다시 시도하십시오.',
    'This stage cannot run because its type is unavailable.' => '이 단계의 유형을 사용할 수 없으므로 단계를 실행할 수 없습니다.',
    'This structure only allows {max} levels.' => '이 구조는 {max}개 레벨까지만 허용합니다.',
    'This will bypass the remaining workflow requirements and approve the draft. Are you sure?' => '남은 워크플로 요구 사항을 건너뛰고 드래프트를 승인합니다. 계속하시겠습니까?',
    'This will discard all approvals and restart the workflow from its first stage. Are you sure?' => '모든 승인을 취소하고 워크플로를 첫 번째 단계부터 다시 시작합니다. 계속하시겠습니까?',
    'This workflow cannot be deleted while it is assigned to a section.' => '이 워크플로는 섹션에 할당되어 있는 동안 삭제할 수 없습니다.',
    'Titles images that are still titled after their filename, in each site’s language, when they’re uploaded or analyzed.' => '이미지를 업로드하거나 분석할 때 아직 파일 이름이 제목인 이미지에 각 사이트의 언어로 제목을 붙입니다.',
    'Toggle menu' => '메뉴 토글',
