    'Translatable' => '번역 가능',
    'Transparent' => '투명',
    'Type <kbd>$</kbd> to choose an environment variable, <kbd>@</kbd> to choose an alias, or <kbd>{</kbd> to choose an object template variable.' => '환경 변수를 선택하려면 <kbd>$</kbd>, 별칭을 선택하려면 <kbd>@</kbd>, 객체 템플릿 변수를 선택하려면 <kbd>{</kbd>를 입력하십시오.',
    'Type <kbd>$</kbd> to choose an environment variable, or <kbd>@</kbd> to choose an alias.' => '환경 변수를 선택하려면 <kbd>$</kbd>, 별칭을 선택하려면 <kbd>@</kbd>를 입력하십시오.',
    'Type <kbd>$</kbd> to choose an environment variable, or enter a Twig template that outputs an ID.' => '환경 변수를 선택하려면 <kbd>$</kbd>를 입력하거나, ID를 출력하는 Twig 템플릿을 입력하십시오.',
    'Type <kbd>$</kbd> to choose an environment variable, or enter a Twig template that outputs comma-separated IDs.' => '환경 변수를 선택하려면 <kbd>$</kbd>를 입력하거나, 쉼표로 구분된 ID를 출력하는 Twig 템플릿을 입력하십시오.',
    'Type <kbd>$</kbd> to choose an environment variable.' => '환경 변수를 선택하려면 <kbd>$</kbd>를 입력하십시오.',
    'Type <kbd>{</kbd> to choose a user property.' => '사용자 속성을 선택하려면 <kbd>{</kbd>를 입력하십시오.',
    'Type <kbd>{</kbd> to choose an object template variable.' => '객체 템플릿 변수를 선택하려면 <kbd>{</kbd>를 입력하십시오.',
    'Type <kbd>{{</kbd> to choose a message variable.' => '메시지 변수를 선택하려면 <kbd>{{</kbd>를 입력하십시오.',
