    'What do you want to do with any content that is only available in {siteName}?' => '{siteName}에서만 사용할 수 있는 콘텐츠를 어떻게 처리하시겠습니까?',
    'What this release will be called in the control panel.' => '제어판에서 이 릴리스를 호출하는 것입니다.',
    'What this workflow will be called in the control panel.' => '제어판에서 이 워크플로를 호출하는 것입니다.',
    'When a workflow is approved:' => '워크플로가 승인될 때:',
