    'When changes are requested:' => '변경이 요청될 때:',
    'Where' => '조건',
    'Whether Craft should generate public URLs for assets in this volume.' => 'Craft가 이 볼륨의 에셋에 대해 공개 URL을 생성할지 여부입니다.',
    'Whether Craft should generate public URLs for transforms stored on a custom output disk.' => 'Craft가 사용자 지정 출력 디스크에 저장된 변환에 대해 공개 URL을 생성할지 여부입니다.',
