    'The base URL for the site.' => '사이트에 대한 기본 URL.',
    'The base URL to the files in this filesystem. This can begin with an environment variable or alias.' => '이 파일 시스템에 있는 파일의 기본 URL입니다. 환경 변수나 별칭으로 시작할 수 있습니다.',
