    'The base folder path that should be used as the root of the filesystem. This can begin with an environment variable or alias.' => '파일 시스템의 루트로 사용할 기본 폴더 경로입니다. 환경 변수나 별칭으로 시작할 수 있습니다.',
    'The base folder path that should be used as the root of the filesystem.' => '파일 시스템의 루트로 사용해야 하는 기본 폴더 경로입니다.',
    'The developer recommends using <a href="{url}">{name}</a> instead.' => '개발자는 대신 <a href="{url}">{name}</a> 사용을 권장합니다.',
    'The draft could not be saved.' => '드래프트를 저장할 수 없습니다.',
    'The draft has been saved.' => '드래프트가 저장되었습니다.',
