    'The field layout is invalid.' => '필드 레이아웃이 잘못되었습니다.',
    'The file failed to upload to the server properly.' => '파일이 서버에 올바르게 업로드되지 않았습니다.',
    'The file “{name}” does not appear to be an image.' => '“{name}” 파일은 이미지가 아닌 것 같습니다.',
    'The filesystem doesn’t contain any files.' => '파일 시스템에 파일이 없습니다.',
    'The following <a href="{url}">aliases</a> are defined:' => '다음 <a href="{url}">별칭</a>이 정의되어 있습니다:',
    'The following content is for preview only.' => '다음 콘텐츠는 미리보기 전용입니다.',
    'The following licensing {total, plural, =1{issue} other{issues}} can be resolved with a single purchase on Craft Console:' => '다음 라이선싱 {total, plural, =1{문제} other{문제}}는 Craft Console에서 라이선스 하나를 구매하면 해결할 수 있습니다:',
    'The following {items} could not be found or are empty. Should they be deleted from the index?' => '다음 {items}(을)를 찾을 수 없거나 비어 있습니다. 인덱스에서 삭제하시겠습니까?',
    'The following {items} could not be found. Should they be deleted from the index?' => '다음 {items}(을)를 찾을 수 없습니다. 인덱스에서 삭제할까요?',
    'The format that {type} titles should take when generated.' => '{type} 제목을 생성할 때 사용할 형식입니다.',
    'The image format that transformed images should use.' => '이미지를 변형시킨 이미지 형식은 사용해야 합니다.',
    'The image format “{format}” is not supported.' => '“{format}” 이미지 형식은 지원되지 않습니다.',
    'The label text to display beside the lightswitch’s disabled state.' => '라이트스위치의 비활성 상태 옆에 표시되는 라벨 텍스트입니다.',
    'The label text to display beside the lightswitch’s enabled state.' => '라이트스위치의 활성 상태 옆에 표시되는 라벨 텍스트입니다.',
    'The language content in this site will use.' => '이 사이트 내 콘텐츠에 사용할 언어입니다.',
    'The language that the control panel should use.' => '제어판에 사용할 언어.',
    'The link types that should be available when inserting links.' => '링크를 삽입할 때 사용할 수 있는 링크 유형입니다.',
    'The loaded project config has more recent changes than your project config YAML files.' => '로드된 프로젝트 구성의 최신 변경 사항이 프로젝트 구성 YAML 파일보다 더 많습니다.',
    'The locale that should be used for date and number formatting.' => '날짜와 숫자 서식에 사용할 로케일.',
    'The location where assets can be selected from.' => '에셋을 선택할 수 있는 위치입니다.',
    'The maximum length (in bytes) the field can hold.' => '항목이 저장할 수 있는 최대 크기(바이트 기준)',
    'The maximum number of authors that entries in this section can have.' => '이 섹션의 항목에 포함될 수 있는 최대 작성자 수입니다.',
    'The maximum number of characters or bytes the field is allowed to have.' => '필드에 포함하도록 허용되는 최대 문자 또는 바이트 수입니다.',
    'The maximum number of levels this category group can have.' => '이 카테고리 그룹에 포함될 수 있는 최대 레벨 수입니다.',
    'The maximum number of levels this section can have.' => '이 섹션에 포함될 수 있는 최대 레벨 수입니다.',
    'The maximum number of rows the field is allowed to have.' => '필드가 보유할 수 있는 열의 최대 수입니다.',
    'The maximum number of {type} that may be selected.' => '선택할 수 있는 {type}의 최대 개수입니다.',
    'The maximum number of {type} the field is allowed to have.' => '필드에 포함될 수 있는 최대 {type} 수입니다.',
    'The minimum number of authors that entries in this section can have.' => '이 섹션의 항목에 포함될 수 있는 최소 작성자 수입니다.',
    'The minimum number of rows the field is allowed to have.' => '필드가 보유할 수 있는 열의 최소 수입니다.',
    'The minimum number of {type} that may be selected.' => '선택할 수 있는 {type}의 최소 개수입니다.',
    'The minimum number of {type} the field is allowed to have.' => '필드에 포함될 수 있는 최소 {type} 수입니다.',
    'The name, handle, and driver of a registered asset transformer can’t be changed.' => 'The name, handle, and driver of a registered asset transformer can’t be changed.',
    'The number of minutes that timepicker options should be incremented by. (Authors can enter a specific time manually.)' => '타임피커 옵션이 증가되는 시간(분)입니다. (저자는 특정 시간을 수동으로 입력할 수 있습니다.)',
    'The number of seconds that the Retry-After HTTP header should be set to for maintenance mode responses.' => '유지 관리 모드 응답에서 Retry-After HTTP 헤더에 설정할 초 수입니다.',
    'The path can contain variables like `{slug}` or `{author.username}`.' => '경로는 `{slug}` 또는 `{author.username}` 같은 변수를 포함할 수 있습니다.',
    'The path to a template file within your `templates/` folder.' => '`templates/` 폴더 내의 템플릿 파일에 대한 경로.',
    'The plugin was removed successfully.' => '플러그인이 제거되었습니다.',
    'The posted condition config is invalid.' => '전송된 조건 구성이 잘못되었습니다.',
    'The primary site cannot be disabled.' => '기본 사이트는 비활성화할 수 없습니다.',
    'The primary site will be loaded by default on the front end.' => '기본 사이트는 기본적으로 프런트 엔드에 로드됩니다.',
    'The request could not be understood by the server due to malformed syntax.' => '비정형 구문으로 인해 서버에서 요청을 인식하지 못했습니다.',
    'The requested URL was not found on this server.' => '요청된 URL을 이 서버에서 찾을 수 없습니다.',
    'The selected condition class is invalid.' => '선택한 조건 클래스가 잘못되었습니다.',
    'The selected {relatedType} {count, plural, =1{contains} other{contain}} validation errors, preventing this {type} from being saved. Edit the {relatedType} to fix them.' => '선택한 {relatedType}에 유효성 검사 오류가 {count, plural, =1{있으므로} other{있으므로}}, 이 {type}을(를) 저장할 수 없습니다. {relatedType}을(를) 편집하여 오류를 수정하십시오.',
    'The selected {type} could not be found.' => '선택한 {type}을(를) 찾을 수 없습니다.',
    'The server doesn’t meet Craft’s new requirements:' => '서버가 Craft의 새 요구 사항을 충족하지 않습니다.',
    'The subpath cannot overlap with any other volumes sharing the same filesystem.' => '하위 경로는 동일한 파일 시스템을 공유하는 다른 볼륨과 겹칠 수 없습니다.',
    'The template Craft CMS will use for HTML emails' => 'Craft CMS가 HTML 이메일에 대해 사용할 템플릿',
    'The template Craft CMS will use for HTML emails. Leave blank to use the default template.' => 'Craft CMS가 HTML 이메일에 사용할 템플릿입니다. 기본 템플릿을 사용하려면 비워 두십시오.',
    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => '템플릿은 `element` 및 `static` 변수를 받습니다. 출력은 정리된 후 비대화형 콘텐츠로 표시되며, 양식 컨트롤, 스크립트, 등록된 에셋은 지원되지 않습니다.',
    'The template will be rendered with an `element` variable.' => '템플릿이 `element` 변수로 렌더링됩니다.',
    'The text label for the entry creation button.' => '항목 생성 버튼의 텍스트 레이블입니다.',
    'The text label for {type} selection buttons.' => '{type} 선택 버튼의 텍스트 레이블입니다.',
    'The text that will be shown if the field doesn’t have a value.' => '필드에 값이 들어 있지 않을 경우 표시되는 텍스트.',
    'The total number of {type} to display per page within the element index.' => '요소 인덱스 내에서 페이지당 표시할 총 {type} 수입니다.',
    'The update can’t be installed :( {message}' => '업데이트를 설치할 수 없습니다:( {message}',
    'The update was reverted successfully.' => '업데이트를 되돌렸습니다.',
    'The uploaded file exceeds the maximum allowed size.' => '업데이트된 파일이 최대 허용 크기를 초과합니다.',
    'The user photo provided is not an image.' => '제공된 사용자 사진이 이미지가 아닙니다.',
    'The user photo provided is not valid.' => '제공된 사용자 사진이 올바르지 않습니다.',
    'The values are matched inclusively.' => '값은 포괄적으로 일치합니다.',
    'The volume where pasted or dropped files should be uploaded.' => '붙여넣거나 끌어다 놓은 파일을 업로드할 볼륨입니다.',
    'The volumes that should be available when selecting assets.' => '에셋을 선택할 때 사용할 수 있는 볼륨입니다.',
    'The {attribute} field must be a string or array.' => '{attribute} 필드는 문자열 또는 배열이어야 합니다.',
    'The {attribute} field must contain a `class` value.' => '{attribute} 필드에는 `class` 값이 포함되어야 합니다.',
    'The {field} field’s {setting} setting has an invalid subpath (“{subpath}”).' => '{field} 필드의 {setting} 설정에 잘못된 하위 경로(“{subpath}”)가 있습니다.',
    'The {field} field’s {setting} setting is set to an invalid volume.' => '{field} 필드의 {setting} 설정이 잘못된 볼륨으로 설정되었습니다.',
    'The {name} license is attached to a different Craft CMS license. You can <a class="go" href="{detachUrl}">detach it in Craft Console</a> or <a class="go" href="{buyUrl}">buy a new license</a>.' => '{name} 라이선스가 다른 Craft CMS 라이선스에 연결되어 있습니다. <a class="go" href="{detachUrl}">Craft 콘솔에서 분리</a>하거나 <a class="go" href="{buyUrl}">새 라이선스를 구입</a>할 수 있습니다.',
    'The {name} license is invalid.' => '{name} 라이선스가 잘못되었습니다.',
    'The {numEntries, plural, =1{entry} other {entries}} will be updated once the {numUsers, plural, =1{user is} other{users are}} deleted.' => '{numUsers, plural, =1{사용자} other{사용자}}가 삭제된 후에 {numEntries, plural, =1{항목} other {항목}}이 업데이트됩니다.',
    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => '{numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}}이(가) 삭제된 후에 {numRelations, plural, =1{관계} other {관계}}가 제거됩니다.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{{targetTypeSingular}은(는)} other{{targetTypePlural}은(는)}} 다른 {numSources, number}개 {numSources, plural, =1{요소} other{요소}}의 필드에서 참조되고 있습니다.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} related by {numRelations, number} other {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}.' => '해당 {numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}}은(는) {numRelations, number}개의 기타 {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}과(와) 관련되어 있습니다.',
    'The {type} is invalid.' => '{type}이(가) 잘못되었습니다.',
    'The “From” name Craft CMS will use when sending email.' => 'Craft CMS가 이메일을 보낼 때 "송신" 항목에 사용할 이름.',
    'Theme' => '테마',
    'There are no available plugins.' => '이용 가능한 플러그인이 없습니다.',
    'There was a problem activating the user: {error}' => '사용자를 활성화하는 중에 문제가 발생했습니다: {error}',
    'There was a problem deactivating the user.' => '사용자를 비활성화하는 중에 문제가 발생했습니다.',
    'There was a problem impersonating this user.' => '이 사용자를 가장하는 동안 문제가 발생했습니다.',
    'There was a problem indexing assets.' => '자산을 인덱싱하는 중에 문제가 발생했습니다.',
    'There was a problem sending the password reset email.' => '비밀번호 재설정 이메일을 보내는데 문제가 있습니다.',
    'There was a problem with uploading the file.' => '파일 업데이트 중에 문제가 발생했습니다.',
    'There was a problem with writing the file to the disk.' => '파일을 디스크에 쓰는 데 문제가 있었습니다.',
    'There was an error relocating the file.' => '파일을 재배치하는 중에 문제가 발생했습니다.',
    'There was an error uploading your photo' => '사진을 업로드하는 동안 오류가 발생했습니다',
    'There was an error uploading your photo: {error}' => '사진을 업로드하는 중에 오류 발생: {error}',
    'This OAuth provider cannot be connected to an account.' => '이 OAuth 공급자는 계정에 연결할 수 없습니다.',
    'This OAuth provider cannot create new users.' => '이 OAuth 공급자는 새 사용자를 생성할 수 없습니다.',
    'This action may only be performed with an elevated session.' => '이 액션은 단계 높은 세션에서만 수행됩니다.',
    'This browser doesn’t support passkeys.' => '이 브라우저는 패스키를 지원하지 않습니다.',
    'This can be left blank if you just want an unlabeled separator.' => '라벨이 없는 구분자를 원하지 않는 한 비워둘 수 없습니다.',
    'This can be set to an environment variable matching one of the option values.' => '이는 옵션 값 중 하나와 일치하는 환경 변수로 설정할 수 있습니다.',
    'This can be set to an environment variable with a boolean value ({examples}).' => '이것은 부울 값({examples})을 사용하여 환경 변수로 설정할 수 있습니다.',
    'This can be set to an environment variable with a valid language ID ({examples}).' => '유효한 언어 ID({examples})를 사용하여 환경 변수로 설정할 수 있습니다.',
    'This can be set to an environment variable with a value of a [supported time zone]({url}).' => '이것은 [supported time zone]({url}) 값을 사용하여 환경 변수로 설정할 수 있습니다.',
    'This can be set to an environment variable, or a Twig template that outputs an ID.' => '이는 환경 변수 또는 ID를 출력하는 Twig 템플릿으로 설정할 수 있습니다.',
    'This can be set to an environment variable, or a Twig template that outputs comma-separated IDs.' => '환경 변수로 설정하거나, 쉼표로 구분된 ID를 출력하는 Twig 템플릿으로 설정할 수 있습니다.',
    'This can begin with an environment variable or alias.' => '환경 변수 또는 별칭으로 시작할 수 있습니다.',
    'This can begin with an environment variable.' => '환경 변수로 시작할 수 있습니다.',
    'This disk is reserved for internal use.' => '이 디스크는 내부용으로 예약되어 있습니다.',
    'This draft’s entry type is no longer available. You can still view it, but not apply it.' => '이 드래프트의 항목 타입은 더 이상 사용할 수 없습니다. 계속해서 볼 수 있지만 적용할 수는 없습니다.',
    'This element is conditional' => '이 요소는 조건부입니다',
    'This entry type’s {attributes} {totalAttributes, plural, =1{has} other{have}} been overridden.' => '이 항목 타입의 {attributes}{totalAttributes, plural, =1{이(가)} other{이(가)}} 재정의되었습니다.',
    'This field has a tip' => '이 필드에는 팁이 있습니다',
    'This field has a warning' => '이 필드에는 경고가 있습니다',
    'This field has been modified.' => '이 필드가 수정되었습니다.',
    'This field is conditional' => '이 필드는 조건부입니다',
    'This field is not set to a valid category group.' => '이 필드는 유효한 카테고리 그룹에 설정되지 않았습니다.',
    'This field is not set to a valid source.' => '이 필드는 유효한 소스에 설정되지 않습니다.',
    'This field is required' => '이 필드는 필수입니다',
    'This field is translatable.' => '이 필드는 변환할 수 있습니다.',
