    'Where do you want to store user photos? Note that the subfolder path can contain variables like {username}.' => '사용자 사진을 어디에 저장하시겠습니까? 하위 폴더 경로에는 {username}과 같은 변수를 사용할 수 있습니다.',
    'Where new {type} should be placed by default in the field.' => '기본적으로 필드에 새로운 {type}을(를) 배치해야 하는 위치입니다.',
    'Where new {type} should be placed by default in the structure.' => '기본적으로 구조에 새로운 {type}을(를) 배치해야 하는 위치입니다.',
    'Where transforms should be stored on the filesystem.' => '변환이 파일 시스템에 저장되는 위치입니다.',
    'Whether HTML should be encoded before rendering the Markdown.' => 'Markdown을 렌더링하기 전에 HTML을 인코딩할지 여부입니다.',
    'Whether authors should be able to choose which time zone the time is in.' => '작성자가 사용하는 시간대를 선택할 수 있는지 여부입니다.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => '선택 모달을 통해 에셋을 선택/업로드하도록 요구하지 않고 저자가 필드에 직접 파일을 업로드할 수 있는지 여부입니다.',
    'Whether buttons should only show their icons, hiding their text labels.' => '버튼에 아이콘만 표시하고, 텍스트 레이블은 숨기는지 여부입니다.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => '이 필드가 포함된 카드 보기에서 필드 이름 대신 사용자 정의 켜기/끄기 레이블을 표시할지 여부입니다.',
    'Whether custom fields should be validated during public registration.' => '공개 등록 중에 사용자 정의 필드의 유효성을 검사해야 하는지 여부입니다.',
    'Whether the editor should show character, word, and line counts.' => '편집기에 문자, 단어, 줄 수를 표시할지 여부입니다.',
    'Whether the editor toolbar should be visible.' => '편집기 도구 모음을 표시할지 여부입니다.',
    'Whether the element index should allow viewing nested {type} in a table.' => '요소 인덱스가 테이블에서 중첩된 {type} 보기를 허용해야 하는지 여부입니다.',
    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => '단락으로 감싸지 않고 인라인 Markdown만 렌더링할지 여부입니다.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => '탐색 메뉴에서 이 소스 옆에 요소 개수를 표시할지 여부입니다.',
    'Whether the site menu should be shown for {type} selection modals.' => '{type} 선택 모달에 대한 사이트 메뉴가 표시되어야 하는지 여부입니다.',
    'Whether the structure of the related {type} should be maintained.' => '관련 {type}의 구조를 유지해야 하는지 여부입니다.',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => '테이블 행을 "기본값" 설정에서 정의한 행으로 제한할지 여부입니다.',
    'Whether this can be dismissed by a user and not shown again.' => '사용자가 해제하고 다시 표시하지 않을 수 있는지 여부입니다.',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => '"다른 사용자의 항목 보기" 권한에 따라, 사용자에게 보기 권한이 없는 항목을 표시할지 여부입니다.',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => '"다른 사용자가 업로드한 파일 보기" 권한에 따라, 사용자에게 보기 권한이 없는 파일을 표시할지 여부입니다.',
    'Whether to show sections that the user doesn’t have permission to view.' => '사용자에게 보기 권한이 없는 섹션을 표시할지 여부입니다.',
    'Whether to show volumes that the user doesn’t have permission to view.' => '사용자에게 보기 권한이 없는 볼륨을 표시할지 여부입니다.',
    'Whether validation errors on the related {type} should prevent the source element from being saved.' => '관련 {type}의 유효화 오류가 소스 요소의 저장을 방해해야 하는지 확인합니다.',
