    'Your changes have been stored.' => '변경 사항이 저장되었습니다.',
    'Your composer.json file could not be located. Try setting the CRAFT_COMPOSER_PATH constant in index.php to its location on the server.' => '사용자의 composer.json 파일을 찾지 못했습니다. index.php의 CRAFT_COMPOSER_PATH 상수를 서버상의 위치로 설정해 보십시오.',
    'Your license key is invalid.' => '유효하지 않은 라이선스 키입니다.',
    'Your project config YAML files are expecting different versions to be installed for the following:' => '프로젝트 구성 YAML 파일은 다음에 다른 버전이 설치되어 있다고 가정합니다:',
    'Your project config YAML files are expecting the following plugins to be installed:' => '프로젝트 구성 YAML 파일은 다음 플러그인이 설치되어 있다고 가정합니다:',
